public String passwordCracker(List<String> passwords, String attempt) {
    List<String> path = solve(passwords, attempt, 0);
    return path == null ? "WRONG PASSWORD" : String.join(" ", path);
}

private List<String> solve(List<String> passwords, String s, int start) {
    if (start == s.length()) return new ArrayList<>();
    for (String pw : passwords) {
        if (s.startsWith(pw, start)) {
            List<String> rest = solve(passwords, s, start + pw.length());
            if (rest != null) {
                rest.add(0, pw);
                return rest;
            }
        }
    }
    return null;
}

