def passwordCracker(self, passwords: list[str], attempt: str) -> str:
    def solve(start: int):
        if start == len(attempt):
            return []
        for pw in passwords:
            if attempt.startswith(pw, start):
                rest = solve(start + len(pw))
                if rest is not None:
                    return [pw] + rest
        return None
    path = solve(0)
    return "WRONG PASSWORD" if path is None else " ".join(path)

