public String passwordCracker(List<String> passwords, String attempt) {
    Set<Integer> failed = new HashSet<>();
    List<String> path = solve(passwords, attempt, 0, failed);
    return path == null ? "WRONG PASSWORD" : String.join(" ", path);
}

private List<String> solve(List<String> passwords, String s, int start, Set<Integer> failed) {
    if (start == s.length()) return new ArrayList<>();
    if (failed.contains(start)) return null;
    for (String pw : passwords) {
        if (s.startsWith(pw, start)) {
            List<String> rest = solve(passwords, s, start + pw.length(), failed);
            if (rest != null) {
                rest.add(0, pw);
                return rest;
            }
        }
    }
    failed.add(start);
    return null;
}

