public String passwordCracker(List<String> passwords, String s) {
    int n = s.length();
    boolean[] dp = new boolean[n + 1];
    int[] parent = new int[n + 1];
    String[] chosen = new String[n + 1];
    dp[0] = true;
    for (int i = 1; i <= n; i++) {
        for (String pw : passwords) {
            int len = pw.length();
            if (i >= len && dp[i - len] && s.startsWith(pw, i - len)) {
                dp[i] = true;
                parent[i] = i - len;
                chosen[i] = pw;
                break;
            }
        }
    }
    if (!dp[n]) return "WRONG PASSWORD";
    Deque<String> out = new ArrayDeque<>();
    for (int i = n; i > 0; i = parent[i]) out.addFirst(chosen[i]);
    return String.join(" ", out);
}

