def passwordCracker(self, passwords: list[str], s: str) -> str:
    n = len(s)
    dp = [False] * (n + 1)
    parent = [0] * (n + 1)
    chosen = [None] * (n + 1)
    dp[0] = True
    for i in range(1, n + 1):
        for pw in passwords:
            ln = len(pw)
            if i >= ln and dp[i - ln] and s.startswith(pw, i - ln):
                dp[i] = True
                parent[i] = i - ln
                chosen[i] = pw
                break
    if not dp[n]:
        return "WRONG PASSWORD"
    out = []
    i = n
    while i > 0:
        out.append(chosen[i])
        i = parent[i]
    return " ".join(reversed(out))

